# 运行器自动生成的文件，每次运行都会覆盖，不要修改。
# Generated by the runner and overwritten on every run; do not edit.
# Helpers every dojo's tests use: fail()/say() report a failure code the web UI has a hint for,
# and Trace records a timeline the UI draws.
import json
import os
import time


def say(zh: str, en: str) -> dict:
    """A message in both languages: say(f"期望 {n} 个", f"expected {n}")."""
    return {"zh": zh, "en": en}


def fail(code: str, msg: dict, **extra) -> None:
    """Stop the test with a failure the UI understands. `code` picks the targeted hint (byCode in
    web/js/dojos/<id>.js); the message is shown as is, in the learner's language, so say what was
    expected, what happened, and the likely cause."""
    __tracebackhide__ = True
    raise AssertionError("DOJO_FAIL " + json.dumps({"code": code, "msg": msg["zh"], "msg_en": msg["en"], **extra}))


class Trace:
    """Events for the UI's timeline: lanes with begin→end bars and marks. Save under the test's name."""

    def __init__(self):
        self.t0 = time.monotonic()
        self.events = []

    def add(self, lane, kind, id, label, bad=False, label_en=None):
        e = {"t": time.monotonic() - self.t0, "lane": lane, "k": kind, "id": id, "label": label, "bad": bad}
        if label_en is not None:
            e["label_en"] = label_en
        self.events.append(e)

    def save(self, name):
        d = os.environ.get("DOJO_TRACE_DIR")
        if d:
            with open(os.path.join(d, name + ".json"), "w") as f:
                json.dump({"t_end": time.monotonic() - self.t0, "events": self.events}, f)
